 * 
 * Searches for "key=" at the beginning of a parameter (start of string or after comma).
 * This ensures we match only complete key names and not substrings within values.
 * 
 * @param config_line The full configuration string
 * @param key The key to search for
 * @return Pointer to the start of the value (after '='), or NULL if not found
 */
static const char* find_key_value(const char* config_line, const char* key) {
    size_t key_len = strlen(key);
    const char* pos = config_line;

    while (*pos != '\0') {
        /* Check if we're at the start of a key (beginning of string or after a comma) */
        if (pos == config_line || *(pos - 1) == ',') {
